type PublicMessageRow struct {
	ID              uuid.UUID  `json:"id"`
	WorkspaceID     uuid.UUID  `json:"workspaceId"`
	Stream          string     `json:"stream"`
	CampaignID      *uuid.UUID `json:"campaignId"`
	ContactID       *uuid.UUID `json:"contactId"`
	ProviderID      *uuid.UUID `json:"providerId"`
	MailboxProvider string     `json:"mailboxProvider"`
	Variant         string     `json:"variant"`
	Email           string     `json:"email"`
}

func (q *Queries) PublicMessage(ctx context.Context, id uuid.UUID) (PublicMessageRow, error) {
	row := q.db.QueryRow(ctx, publicMessage, id)
	var i PublicMessageRow
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.Stream,
		&i.CampaignID,
		&i.ContactID,
		&i.ProviderID,
		&i.MailboxProvider,
		&i.Variant,
		&i.Email,
	)
	return i, err
}

const publicScheduledCampaigns = `-- name: PublicScheduledCampaigns :many
SELECT c.id, c.audience, c.scheduled_at::timestamptz AS scheduled_at
FROM campaigns c
WHERE c.workspace_id = $1 AND c.status IN ('scheduled', 'approved') AND c.deleted_at IS NULL
  AND c.scheduled_at IS NOT NULL AND c.scheduled_at > $2::timestamptz
ORDER BY c.scheduled_at
LIMIT 50
`

type PublicScheduledCampaignsParams struct {
	WorkspaceID uuid.UUID `json:"workspaceId"`
	After       time.Time `json:"after"`
}

type PublicScheduledCampaignsRow struct {
	ID          uuid.UUID       `json:"id"`
	Audience    json.RawMessage `json:"audience"`
	ScheduledAt time.Time       `json:"scheduledAt"`
}

// Upcoming sends, for "Next issue: Tuesday 14 October" on the confirmation page.
func (q *Queries) PublicScheduledCampaigns(ctx context.Context, arg PublicScheduledCampaignsParams) ([]PublicScheduledCampaignsRow, error) {
	rows, err := q.db.Query(ctx, publicScheduledCampaigns, arg.WorkspaceID, arg.After)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []PublicScheduledCampaignsRow{}
	for rows.Next() {
		var i PublicScheduledCampaignsRow
		if err := rows.Scan(&i.ID, &i.Audience, &i.ScheduledAt); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const publicUnsubscribeStats = `-- name: PublicUnsubscribeStats :one
SELECT
    (SELECT count(DISTINCT ce.contact_id) FROM consent_events ce JOIN contacts c ON c.id = ce.contact_id
     WHERE c.workspace_id = $1 AND ce.action = 'unsubscribed' AND ce.occurred_at >= $2
       AND ce.source IN ('unsubscribe_page', 'one_click', 'preference_center'))::bigint AS unsubscribed,
    (SELECT count(DISTINCT ce.contact_id) FROM consent_events ce JOIN contacts c ON c.id = ce.contact_id
     WHERE c.workspace_id = $1 AND ce.action = 'unsubscribed' AND ce.occurred_at >= $2
       AND ce.source = 'one_click')::bigint AS one_click,
    (SELECT count(*) FROM unsubscribe_feedback f WHERE f.workspace_id = $1 AND f.created_at >= $2 AND f.chose_fewer)::bigint AS chose_fewer,
    (SELECT count(*) FROM unsubscribe_feedback f WHERE f.workspace_id = $1 AND f.created_at >= $2 AND NOT f.chose_fewer
       AND f.reason <> 'one_click')::bigint AS answered
`

type PublicUnsubscribeStatsParams struct {
	WorkspaceID uuid.UUID `json:"workspaceId"`
	Since       time.Time `json:"since"`
}

type PublicUnsubscribeStatsRow struct {
	Unsubscribed int64 `json:"unsubscribed"`
	OneClick     int64 `json:"oneClick"`
	ChoseFewer   int64 `json:"choseFewer"`
	Answered     int64 `json:"answered"`
}

// The unsubscribe page tab: departures and answers in the last 30 days.
func (q *Queries) PublicUnsubscribeStats(ctx context.Context, arg PublicUnsubscribeStatsParams) (PublicUnsubscribeStatsRow, error) {
	row := q.db.QueryRow(ctx, publicUnsubscribeStats, arg.WorkspaceID, arg.Since)
	var i PublicUnsubscribeStatsRow
	err := row.Scan(
		&i.Unsubscribed,
		&i.OneClick,
		&i.ChoseFewer,
		&i.Answered,
	)
	return i, err
}
